// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Setup: record original owner
        address originalOwner = c.owner();

        // Ensure caller differs from the owner so that onlyOwner would block them
        vm.assume(caller != originalOwner);

        // Attempt owner change as caller
        vm.prank(caller);
        c.setOwner(caller);

        // After the call, owner must remain unchanged (exclusive control invariant)
        assertTrue(c.owner() == originalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        // Record the current owner before the call
        address ownerBefore = c.owner();

        // Fuzzed caller attempts to change owner to newOwner
        vm.prank(caller);
        bool success;
        try c.setOwner(newOwner) returns (bool result) {
            success = result;
        } catch {
            success = false;
        }

        // After the call, if the caller was the owner before, owner should change.
        // Otherwise, owner must remain unchanged.
        if (caller == ownerBefore) {
            assertEq(c.owner(), newOwner);
        } else {
            assertEq(c.owner(), ownerBefore);
        }
    }
}

