pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != newOwner);
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        address currentOwner = c.owner();
        bool changed = (currentOwner == newOwner && currentOwner != c.owner());
        assertTrue((caller == c.owner() && changed) || (caller != c.owner() && !changed));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // The contract's constructor sets the owner to msg.sender (this test contract).
        // After construction, the owner is address(this).
        // We will use prank to simulate calls from different addresses.
    }
    function testFuzz_property(address caller, address newOwner) public {
        // The only admissible domain restriction: the caller must not be the current owner,
        // because the rule is about non-owner calls.
        vm.assume(caller != c.owner());

        // For the reference contract, a non-owner call to setOwner should revert.
        // We record whether the call reverted.
        bool reverted;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The universal property: the setOwner call must revert when msg.sender is not the owner.
        assertTrue(reverted);
    }
}

